/// <summary>
/// The <c>AVAProcessGuideBackEnabledNavigationAgent</c> class allows bidirectional navigation between steps in a process guide.
/// </summary>
class AVAProcessGuideBackEnabledNavigationAgent extends ProcessGuideNavigationAgent
{
    private ProcessGuideNavigationRouteReversible navigationRoute;
    private ProcessGuideStepName                  stepName;
    private ProcessGuideController                controller;

}

Method.Source:
public void new(ProcessGuideNavigationRouteReversible _navigationRoute, ProcessGuideStepName _stepName, ProcessGuideController _controller)
{
    navigationRoute = _navigationRoute;
    stepName        = _stepName;
    controller      = _controller;
}

protected ProcessGuideStepName calculateNextStepName()
{
    if (controller.parmClickedAction() == WHSMobileAppControlNames::RFPrev)
    {
        return navigationRoute.prevStep(stepName);
    }

    return navigationRoute.nextStep(stepName);
}
